                option
                in [
                    "diffusivity",
                    "exchange-current density",
                    "intercalation kinetics",
                    "interface utilisation",
                    "lithium plating",
                    "loss of active material",
                    "number of MSMR reactions",
                    "open-circuit potential",
                    "particle",
                    "particle mechanics",
                    "particle phases",
                    "particle size",
                    "SEI",
                    "SEI on cracks",
                    "stress-induced diffusion",
