                raise pybamm.OptionError(
                    f"\n'{value}' is not recognized in option '{option}'. "
                    "Values must be strings or (in some cases) "
                    "2-tuples of strings"
                )
        # flatten value
        value_list = []
        for val in value:
            if isinstance(val, tuple):
                value_list.extend(list(val))
            else:
