def _rename_option(options_dict, option_name, old_name, new_name):
    if option_name not in options_dict:
        return

    option = options_dict[option_name]

    if option is None:
        return

    if isinstance(option, str):
        if option == old_name:
            pybamm.logger.warning(
                f"The '{old_name}' {option_name} model has been renamed to '{new_name}'"
            )
            options_dict[option_name] = new_name
        return

    if isinstance(option, tuple):
        # Handle tuple of tuples case
        if isinstance(option[0], tuple):
            # Check if any element contains old_name
            has_old_name = False
            for x in option:
                if isinstance(x, tuple):
                    if isinstance(x[0], tuple):
                        # Handle 2-tuple of 2-tuple of 2-tuple case
                        for y in x:
                            if isinstance(y, tuple):
                                if old_name in y:
                                    has_old_name = True
                    # Handle 2-tuple of 2-tuple case
                    elif old_name in x:
                        has_old_name = True
                elif x == old_name:
                    has_old_name = True

            if has_old_name:
                pybamm.logger.warning(
                    f"The '{old_name}' {option_name} model has been renamed to "
                    f"'{new_name}'"
                )

                # Replace old_name with new_name at any nesting level
                def replace_name(t):
                    if isinstance(t, tuple):
                        return tuple(replace_name(x) for x in t)
                    return new_name if t == old_name else t

                options_dict[option_name] = replace_name(option)

        # Handle single tuple case
        elif old_name in option:
            pybamm.logger.warning(
                f"The '{old_name}' {option_name} model has been renamed to '{new_name}'"
            )
            options_dict[option_name] = tuple(
                new_name if x == old_name else x for x in option
            )


class BatteryModelOptions(pybamm.FuzzyDict):
        # Calculate equivalent resistance of an OCV-R Equivalent Circuit Model
        # ECM overvoltage is OCV minus voltage
        v_ecm = ocv_bulk - V

        # Hack to avoid division by zero if i_cc is exactly zero
        # If i_cc is zero, i_cc_not_zero becomes 1. But multiplying by sign(i_cc) makes
        # the local resistance 'zero' (really, it's not defined when i_cc is zero)
        def x_not_zero(x):
            return ((x > 0) + (x < 0)) * x + (x >= 0) * (x <= 0)

        i_cc = self.variables["Current collector current density [A.m-2]"]
        i_cc_not_zero = x_not_zero(i_cc)
        A_cc = self.param.A_cc

        self.variables.update(
            {
                "Local ECM resistance [Ohm]": pybamm.sign(i_cc)
                * v_ecm
                / (i_cc_not_zero * A_cc),
            }
        )
